/* ===================== BÀI 6 · PC, DPTR và con trỏ ===================== */
/* Bài 6 · PC, DPTR và con trỏ (AMTS-EMB-001-M02-L02, MC51-006) — sinh bởi tools/author/mcu8051/l06.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR6=[{"label":"Ví dụ: PC đi qua từng lệnh","code":"; Ví dụ 1: PC tăng theo độ dài từng lệnh\n        ORG     0000H\n        MOV     A,#12H                  ; 0000H: 2 byte, PC = 0002H\n        INC     A                       ; 0002H: 1 byte, PC = 0003H\n        MOV     30H,#34H                ; 0003H: 3 byte, PC = 0006H\n        SJMP    TIEP                    ; 0006H: PC = 000AH\n        MOV     A,#0FFH                 ; 0008H: bị nhảy qua\nTIEP:   MOV     31H,A                   ; 000AH\n        SJMP    $                       ; 000CH\n        END\n","note":"Bấm Từng bước và đọc PC trong phần Thanh ghi: 0000H → 0002H → 0003H → 0006H, rồi SJMP cộng độ dời 02H vào 0008H để tới 000AH. Lệnh MOV A,#0FFH ở 0008H không bao giờ chạy nên A = 13H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: DPTR = DPH:DPL và INC DPTR","code":"; Ví dụ 2: DPTR gồm DPH (byte cao) và DPL (byte thấp)\n        ORG     0000H\n        MOV     DPTR,#12FEH             ; DPH = 12H, DPL = FEH\n        INC     DPTR                    ; 12FFH\n        INC     DPTR                    ; DPL tràn, nhớ sang DPH\n        MOV     A,DPL                   ; A = ?\n        MOV     B,DPH                   ; B = ?\n        SJMP    $\n        END\n","note":"MOV DPTR,#12FEH có mã 90 12 FE (byte cao trước). Lần INC DPTR thứ hai làm DPL từ FFH về 00H và nhớ sang DPH. Đoán trước: A và B cuối bằng bao nhiêu? (A = DPL = 00H, B = DPH = 13H.)","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Tra bảng CODE bằng MOVC A,@A+DPTR","code":"; Ví dụ 3: đọc bảng trong bộ nhớ chương trình (CODE)\n        ORG     0000H\n        MOV     DPTR,#BANG              ; DPTR = địa chỉ đầu bảng\n        MOV     A,#3                    ; chỉ số trong bảng\n        MOVC    A,@A+DPTR               ; A = byte ở BANG + 3\n        MOV     P1,A                    ; xuất mẫu ra LED\n        SJMP    $\nBANG:   DB      0FEH,0FCH,0F8H,0F0H\n        DB      0E0H,0C0H,80H,00H\n        END\n","note":"Bảng BANG bắt đầu ở 000AH, ngay sau SJMP $. MOVC A,@A+DPTR đọc byte ở 000AH + 3 = 000DH, là F0H; 4 LED P1.0–P1.3 sáng. DPTR vẫn là 000AH sau lệnh.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: R0 làm con trỏ duyệt RAM trong","code":"; Ví dụ 4: R0 làm con trỏ 8 bit duyệt RAM trong\n        ORG     0000H\n        MOV     40H,#11H\n        MOV     41H,#22H\n        MOV     42H,#33H\n        MOV     43H,#44H\n        MOV     R0,#40H                 ; R0 trỏ ô đầu\n        MOV     R7,#4                   ; đếm 4 ô\n        CLR     A\nLAP:    ADD     A,@R0                   ; cộng ô mà R0 đang trỏ\n        INC     R0                      ; trỏ sang ô kế tiếp\n        DJNZ    R7,LAP\n        MOV     30H,A                   ; ô 30H = tổng\n        SJMP    $\n        END\n","note":"R0 là địa chỉ dữ liệu: 40H, 41H, 42H, 43H rồi 44H. PC thì lặp lại ba lệnh LAP, INC, DJNZ bốn lần. 11H + 22H + 33H + 44H = AAH, tổng 28 chu kỳ máy tới SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: DPTR trỏ RAM ngoài, dùng MOVX","code":"; Ví dụ 5: DPTR trỏ RAM ngoài (XDATA), dùng MOVX\n; Giả định bo có RAM ngoài ở 2000H (AT89S52 không có\n; XDATA trên chip); trình mô phỏng có sẵn 64 KB.\n        ORG     0000H\n        MOV     DPTR,#2000H             ; địa chỉ trong XDATA\n        MOV     A,#5AH\n        MOVX    @DPTR,A                 ; ghi XDATA[2000H]\n        INC     DPTR\n        MOV     A,#0A5H\n        MOVX    @DPTR,A                 ; ghi XDATA[2001H]\n        MOV     DPTR,#2000H\n        MOVX    A,@DPTR                 ; đọc lại XDATA[2000H]\n        MOV     R2,A\n        SJMP    $\n        END\n","note":"Hai lệnh MOVX @DPTR,A ghi 5AH vào 2000H và A5H vào 2001H của RAM ngoài (xem phần Bộ nhớ). Nạp lại DPTR = 2000H rồi MOVX A,@DPTR đọc được 5AH. Trên AT89S52 thật cần nối RAM ngoài.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: MOVC A,@A+PC đọc nhầm byte","code":"; Bẫy: MOVC A,@A+PC cộng A với địa chỉ lệnh KẾ TIẾP\n        ORG     0000H\n        MOV     A,#1                    ; muốn lấy BANG[1] = 22H\n        MOVC    A,@A+PC                 ; PC lúc này = 0003H\n        MOV     30H,A\n        SJMP    $\nBANG:   DB      11H,22H,33H\n        END\n","note":"MOVC ở 0002H dài 1 byte nên PC = 0003H khi cộng. A + PC = 0004H, đó là byte 30H của lệnh MOV 30H,A (F5 30), không phải bảng ở 0007H. Đoán trước: A sau MOVC bằng bao nhiêu? (30H.)","dev":{"led":true},"fosc":12000000},{"label":"Sửa: Cộng độ dời trước MOVC A,@A+PC","code":"; Sửa: cộng thêm số byte nằm giữa MOVC và bảng\n        ORG     0000H\n        MOV     A,#1\n        ADD     A,#4                    ; MOV 30H,A và SJMP $: 4 byte\n        MOVC    A,@A+PC                 ; PC = 0005H, A + PC = BANG + 1\n        MOV     30H,A\n        SJMP    $\nBANG:   DB      11H,22H,33H\n        END\n","note":"Giữa lệnh sau MOVC (0005H) và bảng (0009H) có 4 byte, nên cộng thêm 4: A = 5, A + PC = 000AH = BANG + 1, đọc được 22H.","dev":{"led":true},"fosc":12000000}];
const sim6=makeSim51(document.getElementById("m51-l6"),{id:"s6",presets:PR6,ram:256});
makeEx51(document.getElementById("ex-l6"),"l6",[{"t":"Tra bảng mẫu LED","d":"<p>Ô <code>30H<\/code> chứa chỉ số <i>i<\/i> (0–7). Bảng <code>BANG<\/code> có sẵn trong bộ nhớ chương trình (8 byte, mỗi byte làm sáng đúng một LED). Đọc <code>BANG[i]<\/code>, ghi vào ô <code>31H<\/code> và xuất ra cổng <code>P1<\/code>. Không sửa bảng. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 03H<\/code> → <code>31H = F7H<\/code>, <code>P1 = F7H<\/code> (LED P1.3 sáng).<\/p>","start":"        ORG     0000H\n; Viết code ở đây: 31H và P1 = BANG[ô 30H]\n        SJMP    $\nBANG:   DB      0FEH,0FDH,0FBH,0F7H\n        DB      0EFH,0DFH,0BFH,7FH\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":238}},"expect":{"iram":{"0x30":3,"0x31":247},"ports":{"P1":247}}},{"setup":{"iram":{"0x30":0,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":254},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":7,"0x31":238}},"expect":{"iram":{"0x30":7,"0x31":127},"ports":{"P1":127}}},{"setup":{"iram":{"0x30":5,"0x31":238}},"expect":{"iram":{"0x30":5,"0x31":223},"ports":{"P1":223}}},{"setup":{"iram":{"0x30":1,"0x31":238}},"expect":{"iram":{"0x30":1,"0x31":253},"ports":{"P1":253}}},{"setup":{"iram":{"0x30":6,"0x31":238}},"expect":{"iram":{"0x30":6,"0x31":191},"ports":{"P1":191}}}]},"hints":["Bảng nằm trong CODE, không phải RAM trong: chỉ đọc được bằng MOVC.","Nạp địa chỉ đầu bảng vào DPTR bằng MOV DPTR,#BANG, đưa chỉ số vào A.","Sau MOVC, A đã là phần tử của bảng: chỉ còn ghi nó ra đúng hai nơi đề yêu cầu."],"why":"Nhãn BANG là một địa chỉ trong bộ nhớ chương trình. MOV A,BANG sẽ đọc ô RAM trong có địa chỉ trùng byte thấp của nhãn, không phải bảng. Con trỏ 16 bit DPTR cộng với A (MOVC A,@A+DPTR) mới tới đúng byte trong CODE."},{"t":"Chép khối bằng hai con trỏ","d":"<p>Ô <code>30H<\/code> chứa số byte <i>N<\/i> (1–8). Chép <i>N<\/i> byte từ <code>40H<\/code> trở đi sang <code>50H<\/code> trở đi, giữ đúng thứ tự. Các ô nguồn và các ô đích sau <code>50H + N − 1<\/code> phải giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 04H<\/code>, <code>40H..43H = 11H 22H 33H 44H<\/code> → <code>50H..53H = 11H 22H 33H 44H<\/code>, <code>54H<\/code> không đổi.<\/p>","start":"        ORG     0000H\n        MOV     R7,30H                  ; số byte cần chép\n        MOV     R0,#40H                 ; con trỏ nguồn\n; Viết code chép sang 50H.. ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":4,"0x40":17,"0x41":34,"0x42":51,"0x43":68,"0x44":85,"0x45":102,"0x46":119,"0x47":136,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}},"expect":{"iram":{"0x40":17,"0x41":34,"0x42":51,"0x43":68,"0x44":85,"0x45":102,"0x46":119,"0x47":136,"0x50":17,"0x51":34,"0x52":51,"0x53":68,"0x54":238,"0x55":238,"0x56":238,"0x57":238}}},{"setup":{"iram":{"0x30":1,"0x40":165,"0x41":1,"0x42":2,"0x43":3,"0x44":4,"0x45":5,"0x46":6,"0x47":7,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}},"expect":{"iram":{"0x40":165,"0x41":1,"0x42":2,"0x43":3,"0x44":4,"0x45":5,"0x46":6,"0x47":7,"0x50":165,"0x51":238,"0x52":238,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}}},{"setup":{"iram":{"0x30":8,"0x40":255,"0x41":0,"0x42":128,"0x43":127,"0x44":1,"0x45":2,"0x46":3,"0x47":4,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}},"expect":{"iram":{"0x40":255,"0x41":0,"0x42":128,"0x43":127,"0x44":1,"0x45":2,"0x46":3,"0x47":4,"0x50":255,"0x51":0,"0x52":128,"0x53":127,"0x54":1,"0x55":2,"0x56":3,"0x57":4}}},{"setup":{"iram":{"0x30":3,"0x40":0,"0x41":0,"0x42":0,"0x43":9,"0x44":9,"0x45":9,"0x46":9,"0x47":9,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}},"expect":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":9,"0x44":9,"0x45":9,"0x46":9,"0x47":9,"0x50":0,"0x51":0,"0x52":0,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}}},{"setup":{"iram":{"0x30":2,"0x40":90,"0x41":195,"0x42":1,"0x43":1,"0x44":1,"0x45":1,"0x46":1,"0x47":1,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}},"expect":{"iram":{"0x40":90,"0x41":195,"0x42":1,"0x43":1,"0x44":1,"0x45":1,"0x46":1,"0x47":1,"0x50":90,"0x51":195,"0x52":238,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}}},{"setup":{"iram":{"0x30":7,"0x40":7,"0x41":6,"0x42":5,"0x43":4,"0x44":3,"0x45":2,"0x46":1,"0x47":0,"0x50":238,"0x51":238,"0x52":238,"0x53":238,"0x54":238,"0x55":238,"0x56":238,"0x57":238}},"expect":{"iram":{"0x40":7,"0x41":6,"0x42":5,"0x43":4,"0x44":3,"0x45":2,"0x46":1,"0x47":0,"0x50":7,"0x51":6,"0x52":5,"0x53":4,"0x54":3,"0x55":2,"0x56":1,"0x57":238}}}]},"hints":["Cần hai con trỏ 8 bit: R0 cho nguồn, R1 cho đích (chỉ R0, R1 dùng được với @).","Không có lệnh chép thẳng @R0 sang @R1: đọc vào A rồi ghi ra.","Mỗi vòng chép một byte qua A rồi tăng cả hai con trỏ; số vòng lấy từ ô 30H."],"why":"Mỗi con trỏ giữ một địa chỉ dữ liệu và tăng sau mỗi byte, còn PC vẫn chỉ địa chỉ lệnh trong vòng lặp. DJNZ với R7 = N lặp đúng N lần; bộ thử N = 1 và N = 8 kiểm hai biên, các ô sau vùng đích được đặt sẵn EEH để bắt lỗi chép thừa."},{"t":"Tra 4 chỉ số trong 20 chu kỳ","d":"<p>Bốn ô <code>30H<\/code>–<code>33H<\/code> chứa chỉ số (0–15). Ghi bình phương của từng chỉ số, tra trong bảng <code>BP<\/code> có sẵn, vào <code>34H<\/code>–<code>37H<\/code> theo đúng thứ tự. Code mẫu tra bằng <code>MOVC A,@A+PC<\/code>, cho kết quả đúng nhưng chạy 22 chu kỳ máy. Viết lại để chạy không quá <b>20 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và toàn bộ mã kể cả bảng không quá <b>41 byte<\/b>.<\/p><p>Ví dụ: <code>30H..33H = 03H 00H 0FH 07H<\/code> → <code>34H..37H = 09H 00H E1H 31H<\/code>.<\/p>","start":"        ORG     0000H\n; Đúng kết quả nhưng 22 chu kỳ máy: mỗi lần\n; tra phải cộng độ dời từ PC tới bảng BP\n        MOV     A,30H\n        ADD     A,#25                   ; BP - 0005H\n        MOVC    A,@A+PC\n        MOV     34H,A\n        MOV     A,31H\n        ADD     A,#18                   ; BP - 000CH\n        MOVC    A,@A+PC\n        MOV     35H,A\n        MOV     A,32H\n        ADD     A,#11                   ; BP - 0013H\n        MOVC    A,@A+PC\n        MOV     36H,A\n        MOV     A,33H\n        ADD     A,#4                    ; BP - 001AH\n        MOVC    A,@A+PC\n        MOV     37H,A\n        SJMP    $\nBP:     DB      0,1,4,9,16,25,36,49\n        DB      64,81,100,121,144,169,196,225\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":0,"0x32":15,"0x33":7,"0x34":238,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x34":9,"0x35":0,"0x36":225,"0x37":49,"0x30":3,"0x31":0,"0x32":15,"0x33":7}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":238,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x30":0,"0x31":0,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":15,"0x31":15,"0x32":15,"0x33":15,"0x34":238,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x34":225,"0x35":225,"0x36":225,"0x37":225,"0x30":15,"0x31":15,"0x32":15,"0x33":15}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x34":238,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x34":1,"0x35":4,"0x36":9,"0x37":16,"0x30":1,"0x31":2,"0x32":3,"0x33":4}}},{"setup":{"iram":{"0x30":12,"0x31":9,"0x32":6,"0x33":13,"0x34":238,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x34":144,"0x35":81,"0x36":36,"0x37":169,"0x30":12,"0x31":9,"0x32":6,"0x33":13}}},{"setup":{"iram":{"0x30":8,"0x31":10,"0x32":11,"0x33":14,"0x34":238,"0x35":238,"0x36":238,"0x37":238}},"expect":{"iram":{"0x34":64,"0x35":100,"0x36":121,"0x37":196,"0x30":8,"0x31":10,"0x32":11,"0x33":14}}}],"maxCyc":20,"maxBytes":41},"hints":["Đếm chu kỳ từng lệnh của code mẫu: mỗi lần tra có thêm một lệnh ADD A,#… chỉ để bù khoảng cách từ PC tới bảng.","Con trỏ nào trỏ thẳng vào đầu bảng, không phụ thuộc vị trí lệnh MOVC? MOVC A,@A+DPTR không làm đổi con trỏ đó.","Nạp con trỏ bảng một lần ở đầu chương trình; khi đó mỗi lần tra chỉ còn đọc chỉ số, tra, ghi. Đếm lại tổng chu kỳ."],"why":"Với MOVC A,@A+PC, mỗi lệnh MOVC ở một địa chỉ khác nên phải cộng một độ dời khác (25, 18, 11, 4): 4 × (1 + 1 + 2 + 1) + 2 = 22 chu kỳ, 46 byte. DPTR trỏ thẳng đầu bảng và MOVC không làm đổi DPTR, nên nạp một lần: 2 + 4 × 4 + 2 = 20 chu kỳ, 41 byte."}]);

makeQuiz("quiz6","score6",[{"q": "Chương trình bắt đầu ở 0000H: MOV A,#12H (2 byte), INC A (1 byte), MOV 30H,#34H (3 byte). Chạy xong ba lệnh thì PC bằng bao nhiêu?", "o": ["0003H", "0006H", "0005H", "0007H"], "a": 1, "e": "PC tăng theo tổng số byte đã nạp: 2 + 1 + 3 = 6, nên PC = 0006H, địa chỉ của lệnh thứ tư. 0003H là địa chỉ bắt đầu của lệnh thứ ba, không phải PC sau khi nó chạy."}, {"q": "Sau MOV DPTR,#12FFH và INC DPTR, DPH và DPL bằng bao nhiêu?", "o": ["DPH = 13H, DPL = 00H", "DPH = 12H, DPL = 00H", "DPH = 13H, DPL = FFH", "DPH = 12H, DPL = 00H, CY = 1"], "a": 0, "e": "INC DPTR tăng cả 16 bit: 12FFH + 1 = 1300H. Nghĩ DPL tràn mà DPH không đổi là nhầm INC DPTR với INC DPL. INC DPTR không đổi cờ CY."}, {"q": "Lệnh MOVC A,@A+PC nằm ở địa chỉ 0010H, A = 02H. Lệnh đọc byte ở địa chỉ nào trong CODE?", "o": ["0012H", "0013H", "0002H", "0011H"], "a": 1, "e": "MOVC A,@A+PC dài 1 byte nên khi cộng PC = 0011H (lệnh kế tiếp); 0011H + 02H = 0013H. Lấy địa chỉ của chính lệnh MOVC (0010H) là lỗi hay gặp."}, {"q": "Lệnh nào đọc một byte trong bộ nhớ chương trình (CODE)?", "o": ["MOVX A,@DPTR", "MOV A,@R0", "MOV A,DPL", "MOVC A,@A+DPTR"], "a": 3, "e": "Chỉ MOVC đọc CODE. MOVX đọc RAM ngoài, MOV A,@R0 đọc RAM trong, MOV A,DPL chỉ đọc nửa thấp của con trỏ, không đọc ô mà DPTR trỏ tới."}, {"q": "Dòng nào làm trình dịch báo lỗi?", "o": ["INC DPTR", "MOV DPTR,#0FFFH", "DEC DPTR", "DEC DPL"], "a": 2, "e": "8051 chỉ có INC DPTR, không có DEC DPTR. DEC DPL hợp lệ nhưng chỉ giảm byte thấp, không mượn sang DPH khi DPL = 00H."}]);

fillSnips();
